const rows = $('Query Priorities').all().filter(i => i.json.business_name);
const totals = $('Pipeline Total').all().map(i => i.json).filter(t => t.total !== undefined);

// Only one of these two resolver nodes actually runs per execution (schedule vs on-demand).
// Referencing a node that didn't run in this execution throws, so guard each lookup.
function chatIdFrom(nodeName) {
  try {
    const item = $(nodeName).first();
    return item ? item.json.chatId : undefined;
  } catch (e) {
    return undefined;
  }
}
const chatId = chatIdFrom('Resolve Chat Id (Morning)') || chatIdFrom('Resolve Chat Id (On Demand)');

const icon = b => b === 'OVERDUE' ? '\ud83d\udd34' : b === 'DUE_TODAY' ? '\ud83d\udfe0' : b === 'PROPOSAL_PENDING' ? '\ud83d\udfe1' : '\ud83d\udfe2';
const label = (r) => {
  if (r.priority_bucket === 'OVERDUE') return 'Follow-up overdue';
  if (r.priority_bucket === 'DUE_TODAY') return 'Follow-up due today';
  if (r.priority_bucket === 'PROPOSAL_PENDING') return 'Proposal pending';
  if (r.priority_bucket === 'QUALIFIED') return 'Qualified \u2014 needs next step';
  return 'Active';
};

const seen = new Set();
const lines = [];
for (const item of rows) {
  const r = item.json;
  if (seen.has(r.id)) continue;
  seen.add(r.id);
  lines.push(`${icon(r.priority_bucket)} ${r.business_name} \u2014 ${label(r)}`);
}

const pipelineLines = totals.length
  ? totals.map(t => {
      const cur = t.currency || 'INR';
      const valStr = cur === 'INR' ? `INR ${Number(t.total).toLocaleString('en-IN')}` : `${cur} ${Number(t.total).toLocaleString('en-US')}`;
      return `\ud83d\udcb0 Pipeline: ${valStr}`;
    }).join('\n')
  : '\ud83d\udcb0 Pipeline: 0';

const body = lines.length ? lines.join('\n') : 'Nothing urgent today \ud83c\udf89';

return [{ json: {
  chatId,
  text: `\u2600\ufe0f <b>TODAY\'S PRIORITIES</b>\n\n${body}\n\n${pipelineLines}`
} }];
